	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B[k][j]  => scalar ^ (j_vec ^ k_vec)  -> dims: 'k', 'j'
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec);
} tuning;

// Array initialization: exact translation of the C loops using traversers.
//
// Original C:
//   *alpha = 1.5;
//   *beta  = 1.2;
//   for (i = 0; i < ni; i++)
//     for (j = 0; j < nj; j++)
//       C[i][j] = ((i*j+1) % ni) / ni;
//   for (i = 0; i < ni; i++)
