//       A[i][j] = (i*(j+1) % nk) / nk;
//   for (i = 0; i < nk; i++)
//     for (j = 0; j < nj; j++)
//       B[i][j] = (i*(j+2) % nj) / nj;
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// C: i x j  -- outer loop i, inner loop j
	traverser(C).template for_dims<'i'>([=](auto trav_i) {
		trav_i.for_each([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			auto ni = C | get_length<'i'>();
			C[state] = (num_t)((i * j + 1) % ni) / (num_t)ni;
		});
	});

	// A: i x k  -- outer loop i, inner loop k
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		trav_i.for_each([=](auto state) {
			auto [i, k] = get_indices<'i', 'k'>(state);
			auto nk = A | get_length<'k'>();
			A[state] = (num_t)(i * (k + 1) % nk) / (num_t)nk;
		});
	});

	// B: k x j  -- outer loop k, inner loop j
	traverser(B).template for_dims<'k'>([=](auto trav_k) {
		trav_k.for_each([=](auto state) {
			auto [k, j] = get_indices<'k', 'j'>(state);
			auto nj = B | get_length<'j'>();
			B[state] = (num_t)(k * (j + 2) % nj) / (num_t)nj;
		});
	});
