	// initialize C[i][j] = (i*j+1) % ni / ni
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		auto ni     = C | get_length<'i'>();
		C[state]    = (num_t)((i * j + 1) % ni) / (num_t)ni;
	});

	// initialize A[i][k] = i*(k+1) % nk / nk
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto nk     = A | get_length<'k'>();
		A[state]    = (num_t)(i * (k + 1) % nk) / (num_t)nk;
	});

	// initialize B[k][j] = i*(j+2) % nj / nj  (original uses loop var i as row index)
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		auto nj     = B | get_length<'j'>();
		B[state]    = (num_t)(k * (j + 2) % nj) / (num_t)nj;
	});
}

// Main computational kernel: translation of kernel_gemm
// C := alpha * A * B + beta * C
// A: NI x NK (i x k)
// B: NK x NJ (k x j)
// C: NI x NJ (i x j)
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

	// First loop nest:
	// for (i = 0; i < _PB_NI; i++)
	//   for (j = 0; j < _PB_NJ; j++)
	//     C[i][j] *= beta;
	traverser(C).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed, iterates over remaining dims (here 'j')
		trav_i.for_each([=](auto state) {
			C[state] *= beta;
		});
	});

	// Second loop nest:
	// for (i = 0; i < _PB_NI; i++)
	//   for (k = 0; k < _PB_NK; k++)
	//     for (j = 0; j < _PB_NJ; j++)
	//       C[i][j] += alpha * A[i][k] * B[k][j];
	traverser(C, A, B).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed, remaining dims are 'j' and 'k'
		trav_i.template for_dims<'k'>([=](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed, remaining dim is 'j'
			trav_ik.for_each([=](auto state) {
				// state has 'i', 'j', 'k'
				C[state] += alpha * A[state] * B[state];
			});
		});
	});

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;

	// scalars
	num_t alpha;
	num_t beta;

	// common proto-structure that sets the lengths for all three dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk);

	// create bags (data + structure) for C, A, B
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gemm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// output data (for DCE / correctness checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' so we print row-major-like
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
